WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, $h4$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h4$, $t4_0$المادة الرابعة - التزامات شركات التأمين في مجال خدمة ما بعد البيع$t4_0$, $b4_0$تلتزم شركات التأمين بعد إبرام وثائق التأمين بضمان جودة خدمة العملاء واستمراريتها ، ويجب عليها إخطار العملاء في الوقت المناسب وبالوسائل المتفق عليها معهم عند حدوث أي مما يلي :
1- وجود تعديلات على وثائق التأمين أو أية تغييرات جوهرية تتعلق ببيانات الشركة أو مركزها الرئيسي أو فروعها أو في حال تغيير مسئوليها أو ممثليها المختصين بالتعامل مع المؤمن لهم ، ويجب أن تتصف الإخطارات بالوضوح ، والدقة ، والشفافية ، وأن ترسل في التوقيت المناسب .
2- وجود أحداث جوهرية أو طارئة تؤثر في مركز الشركة المالي أو التأميني ؛ كحدوث قوة قاهرة ، أو انخفاض في معدلات العائد على الاستثمار ، أو تغير في أسعار صرف العملات الأجنبية ، أو ارتفاع في قيمة الشيء موضوع التأمين .
3- الإخطار مسبقًا عند رغبة الشركة إدخال أي تعديلات على الأحكام أو الشروط المدرجة في الوثيقة ، مع تقديم مبررات واضحة لذلك خاصة إذا كان التعديل متعلقًا بسياسات الشركة ، مع بيان الأثر المتوقع على حقوق حملة الوثائق والمستفيدين منها ، ولا يجوز إجراء أي تعديل على الوثائق دون الحصول على موافقة كتابية مسبقة من المؤمن له أو حامل الوثيقة وبعد اعتمادها من الهيئة .
كما تلتزم شركات التأمين بإثبات أي تعديلات تطرأ على وثائق التأمين كتابة ، مع بيان واضح لأي مبالغ إضافية قد تترتب على المؤمن لهم نتيجة هذه التعديلات .$b4_0$
