WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h5$, $t5_0$المادة الخامسة - التزامات شركات التأمين في مجال إدارة وحماية حسابات العملاء$t5_0$, $b5_0$تلتزم شركات التأمين في مجال إدارة وحماية حسابات العملاء بما يلي :
1- استيفاء البيانات والمستندات التفصيلية الخاصة بالعملاء أو من ينوب عنهم قانونًا ، مع مراعاة تحديث هذه البيانات بصورة دورية والاحتفاظ بسجلات بيانات تحديد هوية العملاء خاصة المقيمين خارج البلاد وذلك وفقًا لما تقضي به التشريعات الصادرة في هذا الشأن .
2- تمكين المؤمن لهم من الحصول على كشوف حساب دورية عبر وسائل الاتصال المتفق عليها ، تتضمن بيانًا بقيم وثائقهم والأصول أو الاستثمارات المرتبطة بها ، مع أحقية المؤمن لهم في الاعتراض على ما ورد في تلك الكشوف خلال مدة لا تتجاوز خمسة عشر يومًا من تاريخ استلامها وذلك من خلال الوسائل المحددة مسبقًا في التعاقد .
3- إخطار العملاء بمواعيد تجديد وثائق التأمين الخاصة بهم قبل موعد انتهائها بفترة لا تقل عن ثلاثين يومًا وفي حال عدم قيام الشركة بتجديد الوثيقة وجب عليها إخطار العميل مسبقًا وبفترة كافية بأسباب ذلك .
4- إخطار العملاء في نهاية كل سنة مالية بموقف وثائقهم من حيث معدل الأرباح المضافة على حساباتهم الاستثمارية أو على مبالغ التأمين الخاصة بهم أو حصتهم من فائض صندوق التأمين المقرر توزيعه في حالات التأمين التكافلي .
5- في حال توقف العميل ولأول مرة عن سداد أقساط الوثيقة سواء الأساسية أو الإضافية للوثائق المرتبطة بوحدات استثمارية فلا يجوز الخصم من رصيد حساب الوثيقة الاستثماري إلا بعد تخيير العميل بين البدائل الآتية :
البدء في خصم قسط الخطر من رصيد الحساب .
تخفيض مبلغ التغطية التأمينية .
إيقاف التغطية التأمينية وعدم الخصم من رصيد الحساب المتكون .
ويشترط الحصول على موافقة العميل على أحد تلك البدائل ، وفي حال عدم رد العميل على إخطار الشركة خلال المدة المحددة يعد ذلك بمثابة موافقة على الخصم من الحساب الاستثماري وفقًا لشروط الوثيقة ، على أن يكتفى بالإخطار الدوري بعد تنفيذ اختيار العميل .$b5_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
