WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, $h7$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h7$, $t7_0$المادة السابعة - التزامات شركات التأمين عند تحديد الأسعار والعمولات$t7_0$, $b7_0$تلتزم شركات التأمين عند تحديد الأسعار والعمولات الخاصة بوثائق التأمين بما يلي :
1- اتباع الأسس الفنية السليمة والمعتمدة من الهيئة عند تسعير الوثائق التأمينية .
2- إخطار الهيئة بالأسعار المقترحة مرفقًا بها بيان تفصيلي يوضح الأسس الاكتوارية التي تم الاستناد إليها في تحديد هذه الأسعار وذلك قبل بدء تطبيقها بمدة لا تقل عن ثلاثين يومًا لمراجعتها وفقًا للمعايير الفنية والاكتوارية .
3- أن تقدم للهيئة طرق التسعير التي سبق للعملاء الموافقة عليها كجزء من طلبات الموافقة على المنتجات والخدمات التأمينية .$b7_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
