  SELECT id, 8, 0, $h8$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h8$, $t8_0$المادة الثامنة - التزامات شركات التأمين بشأن مطالبات العملاء$t8_0$, $b8_0$في حال وقوع الخطر يلتزم المؤمن لهم أو المستفيدون من الوثيقة بإبلاغ الشركة بذلك وتقديم طلب التعويض خلال عشرة أيام عمل من تاريخ وقوع الخطر أو علمهم به ، ما لم تحدد مدة أخرى لذلك في الوثيقة .
وتلتزم شركات التأمين في مجال التعامل مع مطالبات العملاء بما يلي :
1- تقديم إرشادات وإيضاحات للعملاء بشأن إجراءات تقديم المطالبة واستكمال عملية التسوية وتزويدهم بكافة المعلومات اللازمة ونموذج المطالبة وأرقام الوثائق والمكان الذي يجب التوجه إليه للمطالبة بمستحقاتهم .
2- البدء في فحص المطالبة فور قيام المؤمن لهم بإخطار الشركة ، وعلى الشركة تعيين خبراء معاينة أو مقدري أضرار متى تطلب الأمر ذلك مع إخطار العملاء أو المستفيدين ، وفي حال الاستعانة بخبراء لتقدير حجم الضرر فيتعين عليهم تقديم التقرير النهائي خلال ثلاثين يومًا من تاريخ المطالبة ، ما لم يقتض الأمر خلاف ذلك .
3- تسوية المطالبات بشكل سريع والبت فيها خلال شهر بحد أقصي من تاريخ تقديمها مستوفاة كافة المستندات المتعلقة بها .
4- إخطار العملاء أو المستفيدين كتابة بقرار القبول أو الرفض الكلي أو الجزئي للمطالبة مع توضيح مبررات الرفض بوضوح وشفافية وتسليم العملاء كافة المستندات ذات الصلة بالمطالبة .
5- في حالة قبول المطالبة يجب توضيح آلية احتساب مبلغ التسوية وتقديم المبررات اللازمة في حال التخفيض أو رفض جزء من المطالبة .$b8_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, $h9$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h9$, $t9_0$المادة التاسعة - التزامات شركات التأمين في مجال الدعاية والإعلان عن المنتجات والخدمات التأمينية$t9_0$, $b9_0$تلتزم شركات التأمين في مجال الترويج والدعاية والإعلان عن المنتجات والخدمات التأمينية المقدمة بما يلي :
1- التواصل مع عملائها باستخدام أي وسيلة من وسائل الاتصال التي يختارها العملاء مثل : البريد الإلكتروني ، البريد المسجل ، الرسائل النصية ، تطبيقات الهاتف المحمول ، الخط الساخن ، وللشركات استخدام قنواتها الرئيسية ، الفروع ، والمواقع الإلكترونية وكذلك استخدام قنوات الإعلام العامة المرئية والمسموعة والمقروءة لتسويق منتجاتها باستخدام الأساليب الإعلانية والدعائية والتسويقية التي تراها مناسبة للشرائح المستهدفة ، وبما يتماشى مع الأنظمة واللوائح والتعليمات والقواعد الصادرة من الهيئة .
2- الالتزام بالأساليب المهنية في مجال الترويج والدعاية للمنتجات والخدمات التأمينية ، وأن تتسم كافة المواد الإعلانية والتسويقية بالشفافية ، والصدق ، والأمانة ، والدقة ، وألا تتضمن أي معلومات مضللة أو غير مكتملة ، وأن يتم تقديمها بطريقة واضحة في شكلها ومضمونها وعرضها بأسلوب صحيح وواضح وسهل الفهم .
3- أن تكون المواد التسويقية ملائمة للفئات المستهدفة من حيث العمر ، والثقافة ، والمستوى المادي لكل عميل .
4- ضمان عدم احتواء الإشعارات أو الإعلانات على معلومات شخصية تخص العملاء عند إرسالها لهم عبر وسائل الاتصال المختلفة .
5- أن توضح المادة الإعلانية أو التسويقية خضوع الشركة لإشراف ورقابة الهيئة ، ورقم الترخيص الصادر لها بمزاولة النشاط ، ورقم السجل التجاري .
ويحظر على شركات التأمين القيام بأي مما يلي :
1- تقديم عروض أو نشر بيانات أو معلومات غير صحيحة أو استخدام عبارات من شأنها تضليل أو خداع العملاء ، بشكل مباشر أو غير مباشر .
2- استخدام علامات تجارية لا تخص الشركة في إعلاناتها .
3- عرض إعلانات تسويقية مضللة تتعلق بالأسعار أو الأوضاع المالية للشركة أو تصنيفها من جهات غير معترف بها أو غير مختصة بذلك بما يؤدي إلى تضليل الجمهور .
4- استخدام صيغ المبالغة عند الترويج والدعاية للمزايا التأمينية أو المالية أو أية ميزة تتعدى شروط الوثائق ، أو تقديم بيانات مضللة تتعلق بالتمويلات المقدمة بضمان الوثائق .
5- إخفاء أي بيانات أو معلومات جوهرية ، أو استخدام ألفاظ أو عبارات أو بيانات توضيحية أو أسماء أو عناوين أو أوصاف على الوثائق من شأنها تضليل حملة الوثائق والعملاء المرتقبين ، فيما يتعلق بطبيعة أو مدد المزايا المدفوعة أو نطاق التغطية التأمينية أو الأقساط المقررة أو أي تبعات ضريبية على ذلك .$b9_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins9_0;

WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, $h10$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h10$, $t10_0$المادة العاشرة - العدالة والمساواة بين العملاء$t10_0$, $b10_0$يتعين على شركات التأمين تحقيق العدالة والمساواة بين العملاء ، وتلتزم على وجه الأخص بما يلي :
1- وضع مبادئ مكتوبة ومعلنة تتضمن سياسة واستراتيجية الشركة لتحقيق المعاملة العادلة بين العملاء .
2- استخدام سياسات للمرتبات والعمولات والحوافز للعاملين لديها لا تحث على قبول أخطار إضافية أو غير متوافقة مع احتياجات العملاء ولا تحقق العدالة التأمينية لهم ويسري ذلك أيضًا على شركات الوساطة التأمينية .
3- عدم المغالاة في تحميل العمولات مقدمًا على العملاء .
4- حظر استبدال الوسطاء لوثائق التأمين بدون موافقة العملاء .
5- مراعاة مصالح العملاء والعمل دائمًا على تقديم أفضل الخدمات لتحقيق أعلى درجات الأمان ، وتحقيق أهداف العملاء المالية والتأمينية بما يتناسب مع قدراتهم المادية .
6- التعامل بعدل وأمانة والحرص على مصالح المؤمن لهم والمستفيدين في كافة مراحل العلاقة التعاقدية وتحقيق المساواة بين من تتشابه مراكزهم التأمينية ، كما يجب على الشركات الالتزام بكافة القوانين والقرارات والأنظمة المعمول بها .
7- عدم التمييز أو التفضيل في التعامل بين العملاء الحاليين أو المحتملين بسبب العرق أو الجنس أو الدين أو اللغة ، إلا إذا كان ذلك مبنيًا على أسس اكتوارية أو فنية .
8- في حال تعذر تقديم المنتجات أو الخدمات التأمينية للعملاء ، يحق لهم معرفة أسباب الرفض ، واسترداد المستندات الأصلية المقدمة إلى شركات التأمين .
9- إخطار المؤمن لهم بالعمليات التأمينية التي تم رفضها أو الامتناع عن تنفيذها أو تجديدها مع بيان أسباب ذلك ، وكذا العمليات التي تم إنهاؤها بسبب عدم وفاء العملاء بالتزاماتهم ، وذلك خلال مدة لا تتجاوز ثلاثين يومًا من تاريخ الرفض أو الامتناع أو اتخاذ إجراءات الإنهاء .$b10_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins10_0;

WITH ins11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, $h11$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h11$, $t11_0$المادة الحادية عشرة - حماية خصوصية وسرية بيانات وحسابات العملاء$t11_0$, $b11_0$تلتزم شركات التأمين في مجال حماية خصوصية وسرية بيانات وحسابات العملاء بما يلي :
1- حماية بيانات وحسابات العملاء الشخصية والمالية والتأمينية وعدم استخدامها إلا لأغراض مهنية محددة ومرتبطة بالعمليات التأمينية وعدم الإفصاح عنها إلا بعد الحصول على موافقة كتابية مسبقة من العملاء ووفقًا للتشريعات الصادرة في هذا الشأن ، وذلك باستثناء مراقبي حساباتها ، والخبراء الاكتواريين ، وشركات إعادة التأمين المشتركة .
2- اتخاذ الإجراءات المناسبة وتفعيل الأنظمة الرقابية ، واستخدام التكنولوجيا الحديثة لحماية قواعد بيانات العملاء والمستفيدين واكتشاف ومعالجة الاختراقات أو الاحتيالات التي حدثت أو يحتمل حدوثها .
3- اتخاذ كافة التدابير والإجراءات الأمنية اللازمة لحماية المعلومات المتبادلة إلكترونيًا مع العملاء ، وتوفير أحدث التقنيات والبرمجيات لضمان حماية وسلامة عمليات الدفع الإلكتروني .
4- إدارة كافة المخاطر التي قد يتعرض لها العملاء نتيجة تقديم المنتجات والخدمات التأمينية عبر الوسائل الإلكترونية .
5- الالتزام بالضوابط التكنولوجية وقواعد تأمين المعلومات المتعلقة بإصدار وتوزيع بعض وثائق التأمين النمطية الإلكترونية .
6- تحمل أية أضرار أو خسائر قد تلحق بالعملاء نتيجة حدوث خلل في الأنظمة لدى شركات التأمين أو بسبب عمليات احتيال أو اختراق باستثناء ما ينشأ عن تقصير من جانب العملاء .
7- اتخاذ كافة الإجراءات اللازمة لحماية وثائق التأمين المصدرة إلكترونيًا ضد التزوير والتلاعب مثل استخدام العلامات المائية أو الشعارات البارزة ، وغيرها من الوسائل الفنية .$b11_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins11_0;

WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h12$, $t12_0$المادة الثانية عشرة - السلوك والكفاءة المهنية$t12_0$, $b12_0$تلتزم شركات التأمين في إطار تعزيز السلوك والكفاءة المهنية للمتعاملين مع العملاء بما يلي :
1- التأكد من تمتع وسطاء التأمين ومسئولي المبيعات بأعلى درجات الكفاءة والمهنية والشفافية بما يمكنهم من أداء دورهم على النحو الأمثل في إقناع العملاء بأهمية المنتجات التأمينية ومساعدتهم على اختيار ما يتناسب مع احتياجاتهم التأمينية .
2- ممارسة العاملين بالشركة لأعمالهم بأسلوب مهني مسؤول يتصف بالنزاهة والمصداقية وتحققهم من توافق المنتجات والخدمات المعتمدة للعملاء مع قدراتهم المالية واحتياجاتهم التأمينية على نحو يحقق أفضل مصلحة للعملاء في كافة مراحل تعاملهم مع الشركة ، مع تحمل الشركة المسؤولية الكاملة عن حماية العملاء فيما يقدم إليهم من خدمات ومنتجات تأمينية .
3- توفير العاملين ذوي المؤهلات العلمية والكفاءات والمهارات اللازمة إلى جانب تقديم التدريب الملائم والمستمر لهم خاصة لمن يتعاملون مباشرة مع العملاء مع ضمان إلمامهم الكامل بطبيعة المنتجات والخدمات التأمينية المقدمة .
4- تقييم مستوى الكفاءة المهنية لوسطاء التأمين من خلال تقارير تقييم دورية تعدها الشركة ، على أن تتضمن عناصر تلك التقارير آراء العملاء وتقييمهم لمستوى الخدمات المقدمة ، ومدى اطلاعهم على كافة التفاصيل والمعلومات الواجب توفرها لدى المؤمن له .
5- التأكد من عدم ممارسة وسطاء التأمين لعملهم قبل الحصول على ترخيص مزاولة مهنة الوساطة واستيفائهم كافة المتطلبات والشروط المهنية المطلوبة ، بالإضافة إلى الاهتمام بتنمية قدراتهم المهنية عن طريق التدريب المستمر ، وكذلك تقييمهم عن طريق اختبارات الكفاءة المهنية المتعارف عليها ، ومن خلال توافر نظم الرقابة الداخلية الفعالة ، مع التزامهم ببذل جهود فعالة لتقديم خدمات تأمينية تناسب احتياجات العملاء التأمينية وقدرتهم المالية .
6- التأكد من قيام العاملين بالشركة بواجباتهم والتزاماتهم وتقديم الخدمات بأعلى جودة وفي التوقيتات المناسبة ، بما يحقق مصلحة العملاء والمستفيدين طوال فترة المدة التأمينية .
7- تدريب الوسطاء والعاملين المعنيين بالتوزيع الإلكتروني على آليات التعامل مع وثائق التأمين المصدرة إلكترونيًا والخدمات المرتبطة بها ، مع تزويدهم بالإرشادات اللازمة بما يضمن فهم متطلبات العملاء ويعزز من الشفافية والوضوح ويرفع من مستوى وعي المتعاملين .
8- التأكد من أن العاملين ممن يتعاملون مع العملاء والمستفيدين على إلمام كامل بأفضل الممارسات المهنية في مجال تقديم الخدمات لعملاء شركات التأمين سواء التي تصدر من خلال الهيئة للمهن المرتبطة أو من خلال الاطلاع على التجارب الدولية في هذا الشأن ، وبمراعاة القرارات الصادرة عن الهيئة .
9- وضع سياسات محددة بشأن تجنب حالات تعارض المصالح ، وتحديد الإجراءات اللازمة لضمان التعامل العادل مع كافة العملاء .
10- الإفصاح للعملاء عن أي تعارض محتمل في المصالح بين شركة التأمين وأي أطراف أخرى ، إذا كان لهذا التعارض أثر محتمل على العملاء .
وفي جميع الأحوال يحظر القيام بما يلي :
استقطاب العاملين بشركات التأمين لعملائهم حال الانتقال بين الشركات العاملة بالسوق .
حظر الاشتراك في الممارسة الخاصة بأسعار وثائق التأمين ، إذا كانت هذه الممارسة متصلة بمناقصة عامة أو محدودة لا تزال قائمة .$b12_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins12_0;

WITH ins13_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 13, 0, $h13$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h13$, $t13_0$المادة الثالثة عشرة - التزامات عملاء شركات التأمين$t13_0$, $b13_0$يلتزم كافة عملاء شركات التأمين بالالتزام بمبدأ حسن النية عند استيفاء أي نماذج أو مستندات تطلبها الشركة ، والامتناع عن تقديم أي بيانات أو معلومات مضللة أو خاطئة أو غير مكتملة ، أو الإخلال بواجب الإفصاح عن المعلومات الهامة أو الجوهرية لتجنب بطلان الوثيقة ، ويتعين عليهم القيام بما يلي :
1- قراءة كافة المستندات المقدمة من الشركة بدقة والاطلاع عليها بعناية والتأكد من فهمها بشكل صحيح والتأكد من قدرتهم على الالتزام بمضمونها .
2- الاستفسار من الشركة في حال عدم وضوح أي بند أو شرط وارد في وثيقة التأمين أو في أي مستند آخر مقدم من الشركة .
3- التحقق من البيانات الواردة في طلبات ووثائق التأمين والتأكد من أنها تتضمن كافة البيانات والمعلومات الأساسية والجوهرية ، ومنها على وجه الأخص ؛ البيانات الشخصية ، وتاريخ سريان التغطية ، وشروط وأحكام التأمين ، وبصفة خاصة شروط التصفية والإلغاء ، وحدود واستثناءات التغطيات ، وملاحق الوثائق .
4- معرفة طرق تقديم الشكاوى سواء للهيئة أو الشركة .
5- عدم استخدام المنتجات أو الخدمات التأمينية إلا وفقًا للشروط والأحكام الواردة في وثائق التأمين .
6- الامتناع عن طلب منتجات أو خدمات تأمينية لا تتلاءم مع أوضاعهم المالية ، أو مستوى تقبلهم للمخاطر ، أو عدم القدرة على الوفاء بالالتزامات المترتبة على الحصول على تلك المنتجات والخدمات التأمينية .
7- إبلاغ الشركة عن الإجراءات غير المعتادة في المنتجات أو الخدمات المقدمة لهم ، وإخطار الهيئة في حال عدم تجاوب الشركة .
8- الرجوع إلى الشركة في حال عدم قدرتهم على الوفاء بالتزاماتهم التأمينية لمعرفة الخيارات البديلة المتاحة بما يتناسب مع وضعهم المالي .
9- استخدام وسائل التواصل الشخصية والمحددة في العقد المبرم مع الشركة ، والامتناع عن استخدام وسائل تواصل لا تخصهم .
10- تحديث بياناتهم الشخصية بما في ذلك بيانات الاتصال الخاصة بهم ، بشكل مستمر أو عند طلب الشركة ذلك .
11- عدم التوقيع على نماذج غير مكتملة ، والتأكد من اكتمال كافة البيانات والمعلومات الواردة في النماذج قبل التوقيع عليها ، وعدم التوقيع على نماذج فارغة أو غير مكتملة .
12- مراجعة المعلومات والبيانات التي قاموا بإدخالها ضمن نماذج طلبات المنتجات أو الخدمات التأمينية ؛ لضمان دقتها وخلوها من الأخطاء ، وذلك قبل التوقيع عليها .
13- عدم الإفصاح عن معلوماتهم الشخصية أو التأمينية لأي جهة غير الشركة أو الجهات الرسمية المختصة .
14- تزويد الشركات بكافة المعلومات الجوهرية لتحديد احتياجاتهم التأمينية وتقييم المخاطر المرتبطة بها .
15- التأكد من الحصول على نسخ معتمدة من العقود والمستندات الموقعة والاحتفاظ بها في مكان آمن ، وفي حال الوثائق الإلكترونية يحق للمؤمن لهم طلب نسخ ورقية موقعة ومختومة من الشركة أو طلب إرسالها لهم عبر البريد المسجل خلال مدة لا تتجاوز سبعة أيام عمل من تاريخ تقديم الطلب .$b13_0$
  FROM laws WHERE law_no = 77 AND law_year = 2025 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2025-06-26', 'active' FROM ins13_0;

WITH ins14_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 14, 0, $h14$الباب الأول - ضوابط حماية المتعاملين - الفصل الأول - ضوابط حماية المتعاملين مع شركات التأمين$h14$, $t14_0$المادة الرابعة عشرة - لجنة حماية المتعاملين وتسوية المنازعات$t14_0$, $b14_0$تشكل لجنة بقرار من رئيس الهيئة برئاسة نائب رئيس الهيئة وعضوية أعضاء من ذوي الخبرة من داخل أو خارج الهيئة يختارهم رئيس الهيئة ، للنظر والفصل في المنازعات التأمينية المتعلقة بحماية المتعاملين والتي تنشأ بين أي من حملة الوثائق والمستفيدين منها أو الغير وأي من منشآت التأمين المنصوص عليها في البنود من (1 إلى 5) من المادة (3 / أولاً) من قانون التأمين الموحد ، كما تختص اللجنة بالفصل في المنازعات التي تنشأ بين أي من المقيدين بإحدى المهن التأمينية من جانب ومنشآت التأمين المشار إليها من جانب آخر .
وتصدر اللجنة قرارها خلال ثلاثين يومًا من تاريخ استيفاء البيانات والمستندات المطلوبة ، ويتعين إخطار طرفي المنازعة بقرار اللجنة ويكون قرارها نهائيًا واجب التنفيذ بقبول الطرفين له بعدم التظلم منه أمام لجنة التظلمات المنصوص عليها في المادة (214) من قانون التأمين الموحد ، خلال المواعيد القانونية المقررة أو بصدور قرار برفض التظلم .
ويصدر رئيس الهيئة قرارًا بتنظيم عمل اللجنة والإجراءات المتبعة أمامها .$b14_0$
