WITH ins24_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 24, 0, $h24$الباب الأول - ضوابط حماية المتعاملين - الفصل الثالث - ضوابط حماية المتعاملين مع صناديق التأمين الحكومية وصناديق التأمين الخاصة - ثانيًا - أحكام خاصة بصناديق التأمين الحكومية$h24$, $t24_0$المادة الرابعة والعشرون - التزامات عامة$t24_0$, $b24_0$تلتزم صناديق التأمين الحكومية بما يلي :
1- وجود نسختين أصليتين من نموذج الاشتراك أو الوثيقة موقعتين من الفئات المستهدفة من التغطية التأمينية ومعتمدتين من الصندوق ، على أن تسلم إحداهما لجهة تلك الفئات من خلال التوقيع بالاستلام في سجل خاص لذلك .
2- إقرار موقع من الفئات المستهدفة باطلاعهم على نظام الصندوق وفهمهم لكافة محتوياته وعدم وجود أي معلومات غير مفهومة أو غير واضحة لهم .
3- التأكد من صحة البيانات المستوفاة من الفئات المستهدفة وعدم وجود معلومات مضللة أو غير حقيقة بها .$b24_0$
